local H = game:GetService("HttpService")
local out = {}
local hits = {}
for _, d in ipairs(workspace:GetDescendants()) do
	local n = d.Name
	if n:find("GLASS") or n:find("PANORAMIC") or n:find("MULLION") or n:find("WINDOW") then
		local e = {name = n, class = d.ClassName, path = d:GetFullName()}
		if d:IsA("BasePart") then
			e.pos = {d.Position.X, d.Position.Y, d.Position.Z}
			e.size = {d.Size.X, d.Size.Y, d.Size.Z}
			e.transp = d.Transparency
			e.mat = tostring(d.Material)
		end
		hits[#hits + 1] = e
		if #hits > 40 then break end
	end
end
out.hits = hits
return H:JSONEncode(out)
